        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 54.0, "series": [{"data": [[0.0, 37.0], [300.0, 3.0], [100.0, 26.0], [200.0, 9.0]], "isOverall": false, "label": "2. Stats (/api/dashboard/stats)", "isController": false}, {"data": [[0.0, 38.0], [300.0, 1.0], [100.0, 21.0], [200.0, 6.0], [400.0, 1.0]], "isOverall": false, "label": "4. Students (/api/dashboard/students)", "isController": false}, {"data": [[600.0, 2.0], [300.0, 29.0], [700.0, 1.0], [400.0, 13.0], [800.0, 1.0], [200.0, 22.0], [900.0, 1.0], [500.0, 7.0]], "isOverall": false, "label": "1. Auth (/api/auth/login)", "isController": false}, {"data": [[0.0, 54.0], [200.0, 3.0], [100.0, 13.0]], "isOverall": false, "label": "3. Dosen (/api/dashboard/dosen)", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 900.0, "title": "Response Time Distribution"}},
